#!/bin/sh
# v4 배치1 재시도(r2). 실행(프로젝트 루트): sh docker/gemini/hero_v4_batch1r.sh
G="sh docker/gemini/hero_v4_gen.sh"
$G julius_caesar --force "--note=v4b1r2: 후면 idle 칸에 정면 흉갑이 그려짐" "--extra=3행 세 칸은 모두 완전한 뒷모습: 얼굴·흉갑 앞면이 보이면 안 되고 붉은 망토가 등 전체를 덮는다(가운데 칸 포함). 글라디우스는 오른손에 들고 9칸 모두 보임. 흉갑은 밝은 청동(금갈색), 월계관은 9칸 모두 녹색"
$G oda_nobunaga --force "--note=v4b1r2: 배경이 회청색(마젠타 키 실패)" "--extra=배경은 반드시 순수 마젠타 #FF00FF 한 색(회색·하늘색 배경 금지). 창은 9칸 모두 같은 손에 세로로. 진바오리는 짙은 남색 바탕에 금 테두리"
$G charles_martel --force "--note=v4b1r2: 측면 idle·walk2 창 누락(2회 연속)" "--extra=창은 왼손이 아니라 오른손에 쥐고 측면 행에서는 창대가 몸 앞(화면 왼쪽)에 세로로 길게 보이게, 방패는 왼팔에 작게 몸 옆으로. 측면 3칸 모두 창과 방패가 동시에 보인다(가운데 칸·walk2 칸 포함)"
$G leonidas --force "--note=v4b1r2: 측면 walk1 방패가 정면으로 크게 보이고 idle 과 크기 다름" "--extra=둥근 청동 방패는 9칸 모두 같은 크기로 왼팔에. 측면 3칸에서는 방패를 옆에서 본 모습(같은 크기·같은 위치)으로 그리고 걷기 칸에서 방패를 정면으로 돌리지 않는다. 창은 9칸 모두 세로"
